package br.edu.cesar.treinoconecta.treinoconectacore.infraestrutura.core.desafio;
import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.*;
import br.edu.cesar.treinoconecta.treinoconectacore.dominio.core.aluno.AlunoIdentificador;import br.edu.cesar.treinoconecta.treinoconectacore.dominio.core.desafio.*;import br.edu.cesar.treinoconecta.treinoconectacore.dominio.core.desafio.spi.IDesafioRepositorio;import br.edu.cesar.treinoconecta.treinoconectacore.dominio.core.profissional.ProfissionalIdentificador;import dev.sauloaraujo.d5.framework.infraestrutura.AgregadoRepositorioAbstrato;import org.springframework.transaction.annotation.Transactional;
public class DesafioRepositorio extends AgregadoRepositorioAbstrato<DesafioIdentificador,Desafio,Long,DesafioJpa> implements IDesafioRepositorio{
 private final IDesafioRepositorioJpa desafios;private final IAvaliacaoDesafioRepositorioJpa avaliacoes;private final IDesafioInscricaoRepositorioJpa inscricoes;
 public DesafioRepositorio(IDesafioRepositorioJpa desafios,IAvaliacaoDesafioRepositorioJpa avaliacoes,IDesafioInscricaoRepositorioJpa inscricoes){super(desafios,"Desafio %s não encontrado");this.desafios=Objects.requireNonNull(desafios);this.avaliacoes=Objects.requireNonNull(avaliacoes);this.inscricoes=Objects.requireNonNull(inscricoes);}
 protected Long paraIdentificadorJpa(DesafioIdentificador id){return Long.valueOf(id.toString());}
 protected DesafioJpa paraJpa(Desafio d){return new DesafioJpa(d.getIdentificador().map(x->Long.valueOf(x.toString())).orElse(null),d.titulo(),d.indicador().name(),d.vigencia().inicio(),d.vigencia().fim(),d.situacao().name(),OffsetDateTime.now());}
 protected Desafio paraAgregado(DesafioJpa d){return new Desafio(Optional.of(new DesafioIdentificador(d.getIdentificador().toString())),d.getTitulo(),IndicadorDesafio.valueOf(d.getIndicador()),new VigenciaDesafio(d.getInicio(),d.getFim()),SituacaoDesafio.valueOf(d.getStatus()));}
 public Desafio bloquear(DesafioIdentificador id){return paraAgregado(desafios.bloquear(paraIdentificadorJpa(id)).orElseThrow(()->new NoSuchElementException("Desafio não encontrado")));}
 public boolean existeAvaliacaoInicial(DesafioIdentificador d,AlunoIdentificador a){return avaliacoes.existsByDesafioAndAlunoAndTipo(paraIdentificadorJpa(d),Long.valueOf(a.toString()),"INICIAL");}
 public Optional<AvaliacaoDesafio> buscarAvaliacaoInicial(DesafioIdentificador d,AlunoIdentificador a){return avaliacoes.findFirstByDesafioAndAlunoAndTipoOrderByRegistroAsc(paraIdentificadorJpa(d),Long.valueOf(a.toString()),"INICIAL").map(this::paraDominio);}
 public boolean existeInscricao(DesafioIdentificador d,AlunoIdentificador a){return inscricoes.existsByDesafioAndAluno(paraIdentificadorJpa(d),Long.valueOf(a.toString()));}
 public void inscrever(Desafio d,AlunoIdentificador a,IndicadorDesafio i,BigDecimal meta,Long avaliacaoInicial,OffsetDateTime quando){inscricoes.save(new DesafioInscricaoJpa(Long.valueOf(d.getIdentificador().orElseThrow().toString()),Long.valueOf(a.toString()),i.name(),meta,avaliacaoInicial,quando));}
 public AvaliacaoDesafio registrarAvaliacao(DesafioIdentificador d,AlunoIdentificador a,ProfissionalIdentificador p,TipoAvaliacaoDesafio t,BigDecimal peso,BigDecimal cintura,BigDecimal gordura,OffsetDateTime instante){return paraDominio(avaliacoes.save(new AvaliacaoDesafioJpa(paraIdentificadorJpa(d),Long.valueOf(a.toString()),Long.valueOf(p.toString()),t.name(),peso,cintura,gordura,instante)));}
 public Optional<AvaliacaoDesafio> buscarAvaliacao(Long id){return avaliacoes.findByIdentificador(id).map(this::paraDominio);}
 public void alterarAvaliacao(AvaliacaoDesafio a){var j=avaliacoes.findByIdentificador(a.identificador().orElseThrow()).orElseThrow(()->new NoSuchElementException("Avaliação não encontrada"));j.atualizar(a.peso(),a.cintura(),a.gordura());avaliacoes.save(j);}
 public boolean excluirAvaliacao(Long id){if(!avaliacoes.existsById(id))return false;avaliacoes.deleteById(id);return true;}
 public void encerrar(Desafio d){desafios.save(paraJpa(d));}
 private AvaliacaoDesafio paraDominio(AvaliacaoDesafioJpa a){return new AvaliacaoDesafio(Optional.of(a.getIdentificador()),new DesafioIdentificador(a.getDesafio().toString()),new AlunoIdentificador(a.getAluno().toString()),new ProfissionalIdentificador(a.getProfissional().toString()),TipoAvaliacaoDesafio.valueOf(a.getTipo()),a.getPeso(),a.getCintura(),a.getGordura(),a.getRegistro());}
}
